mod solution;

fn main() {
    let cases = [
    (r#"row0=53.678912"#, r#"4"#),
    (r#"row0=53467891."#, r#"2"#),
    (r#"
row0=53467891.
"#, r#"2"#),
    (r#"  
row0=53.678912
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS sudoku");
}
